jsonTools.init:
function init(eli) {
  var OVERLAY_ID = "_eli3_tour_root";
  var Z = 100000;
  var _active = false;
  var _idx = 0;
  var _els = {};
  var _dragPos = null;      // per-step drag offset (reset each stop)
  var _onResize = null;
  var _onKey = null;
  var _relayoutTimer = null;
  var _dlgObserver = null;
  // When the user clicks the highlighted element (e.g. Settings), drop the
  // dim/spotlight so whatever opens is fully usable. The mascot card stays so
  // they can keep going. Reset on each step change.
  var _spotPaused = false;
  var _targetEl = null;
  var _targetClick = null;
  // User-driven minimize (the — button): drops the dim/highlight so the user
  // can see whatever tool/overlay is behind the tour. Toggle, reset per step.
  var _userMin = false;

  function _esc(s) {
    return String(s == null ? "" : s)
      .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;").replace(/'/g, "&#39;");
  }
  function _wait(ms) { return new Promise(function (r) { setTimeout(r, ms); }); }
  function _q(sel) { try { return document.querySelector(sel); } catch (_e) { return null; } }
  // First name for the intro greeting. Use the kernel's identity surface
  // (reads the eli_user_settings blob + Office profile + email), falling back
  // to the raw v2 localStorage keys, then "there".
  function _firstName() {
    try {
      var id = (eli.tools && typeof eli.tools.userIdentity === "function") ? eli.tools.userIdentity() : null;
      if (id) {
        var fn = String(id.firstName || id.name || "").trim().split(/\s+/)[0];
        if (fn) return fn;
      }
    } catch (_e) {}
    try {
      if (eli.compat && eli.compat.lsGet) {
        var n = eli.compat.lsGet("eli_user_first_name") || eli.compat.lsGet("userFirstName")
             || eli.compat.lsGet("eli_user_name") || eli.compat.lsGet("userName");
        if (n) { n = String(n).trim().split(/\s+/)[0]; if (n) return n; }
      }
    } catch (_e) {}
    return "there";
  }
  function _mascot() {
    try { if (eli.ui && typeof eli.ui.mascot === "function") return eli.ui.mascot(); } catch (_e) {}
    return '<div style="font-size:30px;line-height:1;">🤖</div>';
  }
  // Best-effort: find a small visible element under `container` whose title
  // or text matches `re` (for the footer data-upload control, which is a
  // tool-registered slot with no fixed class).
  function _byText(container, re) {
    if (!container) return null;
    var nodes = container.querySelectorAll("*");
    for (var i = 0; i < nodes.length; i++) {
      var n = nodes[i];
      if (!n.offsetParent || n.children.length > 5) continue;
      var t = ((n.getAttribute && (n.getAttribute("title") || n.getAttribute("aria-label") || "")) + " " + (n.textContent || ""));
      if (re.test(t)) return n;
    }
    return null;
  }
  function _closeUnpinned() {
    try {
      var m = _q("#_eli3_unpinned_menu");
      if (m) { var c = _q("._eli3_unpinned_close"); if (c) c.click(); else m.remove(); }
    } catch (_e) {}
  }
  // Find one dashboard tile by its visible label (e.g. "ERROR REVIEW"). Tiles
  // carry no data-id, so match on the .text label. Returns the tile wrap for a
  // clean spotlight; null when off the dashboard. Used by the core-tool stops.
  function _tile(label) {
    var want = String(label || "").toUpperCase().replace(/\s+/g, " ").trim();
    var scope = document.getElementById("_eli3_dashboard_main") || document;
    var btns = scope.querySelectorAll(".tp-btn");
    for (var i = 0; i < btns.length; i++) {
      var txt = btns[i].querySelector(".text");
      if (txt && txt.textContent.toUpperCase().replace(/\s+/g, " ").trim() === want) {
        return btns[i].closest("._eli3_tile_wrap") || btns[i];
      }
    }
    return null;
  }

  // Resume marker — survives a Script Lab reload so the Phase 2 narrator can
  // come back where it left off and stick around for the live Build Draft run.
  // Written on every step of a resumable script; cleared on a normal end.
  var _CFG = window.STORE_CONFIG || "config";
  var RESUME_KEY = "tour_resume";
  var _resumeKind = null; // "build" | "build_resume" | null (set in _startTour)
  function _saveResume(kind, step) { try { if (eli.storage) eli.storage.put(_CFG, { key: RESUME_KEY, resume: kind, step: step || 0 }); } catch (_e) {} }
  function _clearResume() { try { if (eli.storage) eli.storage.delete(_CFG, RESUME_KEY); } catch (_e) {} }

  // Build Draft hub step rows (keyed by data-step-id). Used by the Phase 2
  // resume so the narrator can spotlight each step and auto-tuck on click.
  function _bdStep1() { return _q('._eli3_bd_step[data-step-id="logic"]') || _q("._eli3_bd_step") || _q("._eli3_bd_steps"); }
  function _bdStep2() { return _q('._eli3_bd_step[data-step-id="templates"]') || _q("._eli3_bd_steps"); }
  function _bdStep3() { return _q('._eli3_bd_step[data-step-id="error_review"]') || _q("._eli3_bd_steps"); }
  function _bdStep4() { return _q('._eli3_bd_step[data-step-id="save"]') || _q("._eli3_bd_steps"); }

  // ─── Tour script ──────────────────────────────────────────────────────
  // dim:false → no backdrop/ring (reserved for steps shown over a dialog).
  // Two scripts: STEPS_DASH (Phase 1 dashboard tour) and STEPS_BUILD (Phase 2
  // Build Draft walkthrough). STEPS points at whichever is running.
  var STEPS_DASH = [
    { title: "Hi, welcome to ELI", intro: true, cta: "Continue →",
      body: "I'm ELI — your AI assistant for drafting and reviewing legal documents, built for the EI group. I'll give you a quick guided tour of the dashboard so you know where everything lives. To make it hands-on, I've loaded a sample Consulting Agreement for us to explore together. First, a quick look at what I bring to the table.",
      target: function () { return null; } },
    { title: "What ELI brings", intro: true, cta: "Start the tour →",
      introTitle: "Everything EI works with, built in",
      body: "ELI ships with everything the EI group uses day to day — all 17 of EI's agreement templates and 12 negotiation playbooks built right in. One note: ELI is designed for a screen larger than a laptop, so if something looks small or a little off on your laptop, apologies in advance — it shines on a bigger display. Okay, enough of me blabbing about myself — click Start the tour to take a spin around the dashboard for Phase 1. Phase 2 moves into building a draft, and Phase 3 reviews a revised document.",
      target: function () { return null; } },
    { title: "Home base",
      body: "This is your Home button — tap it any time to come straight back to this dashboard from anywhere in ELI. Remember this icon, you'll use it often.",
      target: function () { return _q(".beta-home-btn"); } },
    { title: "Help & support",
      body: "Click the ELI logo any time for Help, to contact support, or to report a bug. You can even Ask ELI about ELI — a built-in bot that knows the tool inside out and will tell you anything about how ELI works. Your safety net if you ever get stuck.",
      target: function () { return _q(".app-label") || _q(".brand-titles") || _q(".brand-group"); } },
    { title: "Settings",
      body: "Your control center — language, AI model, theme, and admin options all live behind this cog. Go ahead, click the icon and check out the Interface submenu.",
      target: function () { return _q("#btnHeaderSettings"); } },
    { title: "The status bar",
      body: "Along the bottom is a row of quick utilities. Let's look at three of them.",
      target: function () { return _q("._eli3_status_bar"); } },
    { title: "Version history",
      body: "Down here on the right is your version history — ELI automatically saves past versions of your document as you run certain tools. Try it: click the camera to take a snapshot now, then open the history to view it. You can restore any earlier version anytime. And if someone tries to sneak in a redline without tracking it, ELI will know.",
      target: function () { return _q("._eli3_footer_slot_right") || _q("._eli3_status_bar"); } },
    { title: "Zoom",
      body: "Make the panel bigger or smaller to fit your screen — especially handy on a laptop.",
      target: function () { return _q("._eli3_status_zoom") || _q("._eli3_status_zoom_btn") || _q("._eli3_status_bar"); } },
    { title: "OARS data",
      body: "This is your OARS data — the intake details for the request. It's usually uploaded automatically for you, and we'll cover it in more depth in Phase 2.",
      target: function () { return _q("._eli3_footer_slot_left") || _q("._eli3_status_bar"); } },
    { title: "Your toolbar",
      body: "This side rail shows the type of document you're working on plus your stats. Go ahead — click your user stats to explore them, then click the trophy bar at the bottom to see your trophies. Hit the Home button when you're done to come back here.",
      target: function () { return _q("#_eli3_sidebar"); } },
    { title: "Session feed",
      body: "Everything you do this session is saved here. Click the loaded-document entry for a quick summary of the doc — give it a try. You can also click any tool you've used to jump right back in and pick up where you left off.",
      target: function () { return _q("#_eli3_activity_panel") || _q("#_eli3_activity_rail"); } },
    { title: "Ask ELI",
      body: "Right here at the top is Ask ELI — your AI assistant who can answer any question about the document, an EI template (all built-in), or any attachment including a PDF. Save a custom question you use often by clicking the + button, or hit Improve to sharpen your prompt. Go ahead and ask ELI to summarize this document — or anything you want.",
      target: function () { return _q("._eli3_home_ask") || _q("._eli3_home_ask_box") || _q("#_eli3_dashboard_main"); } },
    { title: "More tools",
      body: "Click the + to open every tool you haven't pinned and run it right there — no need to clutter your dashboard. Go ahead and take a peek. And if there's a tool you reach for a lot, click Customize Dashboard to pin it into your other tools so it's always one tap away.",
      target: function () { return _q("#_eli3_add_btn_wrap"); } },
    { title: "Your other tools",
      body: "Below your core tools, this whole area is entirely yours to customize. Pin the tools you reach for, unpin the ones you don't, and add any of ELI's other tools from the + you just saw — things like Docuscrub, Template Searcher, Compare, ELI5, and Build Draft. Plenty more to discover on your own after the demo.",
      target: function () { return _q("._eli3_secondary_wrap") || _q("#_eli3_dashboard_main"); } },
    { title: "Your core tools",
      body: "These three at the top are your core tools — the heart of ELI, always pinned and ready: Error Review, Legal Review, and Final Review. They cover the work you'll do most. Let me walk you through each one.",
      target: function () { return _q("._eli3_primary_row") || _q("#_eli3_dashboard_main"); } },
    { title: "Core tools — Error Review",
      body: "Start with Error Review. It works on any document, not just agreements, and because it's powered by AI it catches errors a spell-checker never would. Go ahead, click it now to give it a try.",
      target: function () { return _tile("ERROR REVIEW") || _q("._eli3_primary_row"); } },
    { title: "Core tools — Legal Review",
      body: "Next, Legal Review — really several review tools working as one. Use it to review any document, whether it was drafted by Colgate or a third party, and it handles redlines too. Based on the answers you give it, ELI figures out which review tool is the right one — so make sure you answer the questions correctly. Go ahead, click it now to give it a try.",
      target: function () { return _tile("LEGAL REVIEW") || _q("._eli3_primary_row"); } },
    { title: "Core tools — Final Review",
      body: "And the third, Final Review — run it before execution to summarize the agreement's key terms into a clean brief for the requester to approve. It also cleans up the document for you, stripping out highlights, double spaces, and other leftover formatting. Hold off on clicking this for now — you'll click it in Phase 3.",
      target: function () { return _tile("FINAL REVIEW") || _q("._eli3_primary_row"); } },
    { title: "That's the tour", intro: true, cta: "Finish",
      introTitle: "That's the end of Phase 1!",
      body: "We covered the essentials, but there's plenty I didn't get to — the rest of your tools, the deeper corners of the dashboard, and all the little touches you'll find as you go. When you're done here, poke around: try a few of the other tools and explore the dashboard on your own. For now, enjoy Phase 2, where you'll learn how ELI builds a draft.",
      target: function () { return null; } },
  ];

  // ─── Phase 2: Build Draft walkthrough ─────────────────────────────────
  // Launched by the Demo Director AFTER the OARS data finishes loading
  // (eli.dispatch("tour", "buildDraft")). Narration splashes — no dashboard
  // spotlights — ending with a pointer to Script Lab's reload arrow.
  var STEPS_BUILD = [
    { title: "Welcome back", intro: true, cta: "Show me →",
      introTitle: "Hi again — let's build a draft",
      body: "Now let me show you Build Draft, the tool that turns your OARS data into a finished, ready-to-send agreement. The best part — it's almost entirely automatic.",
      target: function () { return null; } },
    { title: "Start with OARS data", dim: false, pin: "leftmid",
      body: "Step one is loading your OARS data into Word. You can download it straight from the OARS email, or pull it from OARS itself — then drop it into your document. That's exactly what I just did for this demo.",
      target: function () { return null; } },
    { title: "The rest is automatic", dim: false, pin: "leftmid",
      body: "From here you never click Build Draft — or anything else. Once it starts, ELI reads your OARS data, figures out the correct EI template (chooses from all of the built-in EI templates), and asks you to confirm it's the right one. In a few seconds I'll show you how to kick the whole thing off.",
      target: function () { return null; } },
    { title: "Pick up where you left off", dim: false, pin: "leftmid",
      body: "Need to step away mid-way? No problem — Build Draft saves your progress, so you can leave any time and pick right back up where you left off.",
      target: function () { return null; } },
    { title: "Reload to begin", dim: false, pin: "topleft", setsResume: "build_resume",
      nextLabel: "Click the reload arrow ↻", nextNoop: true,
      body: "How to begin — this is how the whole process starts. Normally you'd just open ELI with your OARS data already in the Word document, and it begins on its own. For this demo, though, look at the very top-left of the window for the circular reload arrow ↻ — that's Script Lab's reload (part of Script Lab, not ELI — ELI's own reload buttons won't do this). Click it to begin the Build Draft process. One thing first: right after it reloads, don't forget to confirm the agreement is a Service Agreement — that confirmation pops up immediately and I won't be there for it. Then I'll reappear in the bottom-right to walk you through the 4 steps.",
      target: function () { return null; } },
  ];

  // ─── Phase 2 resume: after the reload, accompany the live Build Draft run ──
  // Auto-launched on boot when the resume marker is set (eli.dispatch isn't
  // used — init() checks IDB directly). No goHome, so it overlays the Build
  // Draft flow rather than navigating away from it.
  var STEPS_BUILD_RESUME = [
    { title: "Back with you", dim: false, pin: "bottomright",
      body: "And we're back! Build Draft has started, read your OARS data, and you've confirmed the Service Agreement template. Now let's walk through the 4 steps together — I'll stay down here in the corner the whole time. Click Next before clicking Step 1.",
      target: function () { return null; } },
    { title: "Step 1 — Customize the template", nextLabel: "Click Step 1", nextNoop: true, pausedNextLabel: "Only click when done with Step 1",
      body: "Step 1: customize the template for this deal — for example, Mutual NDA vs. One-Way, or Colgate vs. Hill's. Now go ahead and click Step 1 (highlighted here) and answer the questions. I'll tuck into the corner while you work. If you need help during this step, ask my partner (you know, the human). When you're back at the Build Draft hub for Step 2, click Next again to wake me up.",
      target: _bdStep1 },
    { title: "Step 2 — Fill the placeholders", nextLabel: "Click Step 2", nextNoop: true, pausedNextLabel: "Only click when done with Step 2",
      body: "Step 2: fill in the placeholders — things like the third party name, deliverables, and so on. ELI brings in everything it can from your OARS data; you just confirm the rest. Go ahead and click Step 2 now. I'll minimize again while you answer the questions — lean on the human if you need help. When you're back at the hub for Step 3, click Next to bring me back.",
      target: _bdStep2 },
    { title: "Step 3 — Error review", nextLabel: "Click Step 3", nextNoop: true, pausedNextLabel: "Only click when done with Step 3",
      body: "Step 3: error review — ELI runs a full grammar and proofreading scan and flags anything that needs a second look. Go ahead and click Step 3 now. I'll minimize again while you work through it — the human's there if you get stuck. When you're back at the hub for Step 4, click Next to wake me up.",
      target: _bdStep3 },
    { title: "Step 4 — Save & send", nextLabel: "Click Step 4", nextNoop: true, pausedNextLabel: "Only click when done with Step 4",
      body: "Step 4: save & send — a very important step for standardization. ELI names the file and standardizes the email using EI's rules, takes a snapshot for your version history (so later reviews are even more intelligent), and updates the auto fields — no more broken field references! Go ahead and click Step 4 now. I'll minimize one last time while you finish up; click Next when you're back and I'll wrap us up.",
      target: _bdStep4 },
    { title: "That's Build Draft", dim: false, pin: "bottomright",
      body: "And that's Build Draft, start to finish. After this demo, feel free to try other templates. Now you can let the human know you're ready for Phase 3. Good job so far!",
      target: function () { return null; } },
  ];

  // ─── Phase 3 stage 1: reload prompt ───────────────────────────────────
  // After the Demo Director loads the revised draft it dispatches
  // tour:reviewReload — a single pinned card telling the user to reload ELI
  // (so it reads the draft) and click Phase 3 again for the walkthrough.
  var STEPS_REVIEW_RELOAD = [
    { title: "Reload to start Phase 3", dim: false, pin: "topleft", nextLabel: "Click reload button", nextNoop: true, setsResume: "review",
      body: "I've loaded the actual revised draft the EI team received. For Legal Review to read it, reload ELI now using the circular arrow ↻ at the very top-left of the window (that's Script Lab's reload — ELI's own reload buttons won't do this). Once it reloads, I'll come right back and walk you through Legal Review. As a reminder, you won't need to click reload when you're reviewing a document for real — it's only necessary here in the training because you just built a draft, and we don't want to confuse ELI. Normally you wouldn't draft a document and review a document in the exact same Word document.",
      target: function () { return null; } },
  ];

  // ─── Phase 3 stage 2: Legal Review walkthrough ────────────────────────
  // Launched by the Demo Director on the SECOND Phase 3 click, after the
  // reload (eli.dispatch("tour", "reviewDraft")). Legal Review stays
  // spotlighted on the explanatory stops; the user is told to hold off
  // clicking until the final stop.
  function _lrTile() { return _tile("LEGAL REVIEW") || _q("._eli3_primary_row"); }
  function _frTile() { return _tile("FINAL REVIEW") || _q("._eli3_primary_row"); }
  // Final Review wizard elements (present after the Final Review tile is clicked).
  function _frType() { return _q("#ebTypeSel"); }
  function _frReq() { return _q("#ebReqSel"); }
  function _frProceed() { return _q("#ebRunBtn"); }   // Proceed to DocuScrub
  function _frScrub() { return _q("#btnRunScrub"); }   // Scrub Document → Proceed to Approval Email (step 1)
  function _frGenEmail() { return _q("#ebGenEmailBtn"); } // Generate Approval Email (step 2)
  function _askEliBar() { return _q("._eli3_home_ask"); }  // Ask ELI bar on the dashboard
  function _askFocusHeader() { return _q("#_eli3_chat_selchip"); } // focus header above the Ask ELI input
  function _copyFnBtn() { return _q("[data-oars-fn-btn]") || _q("._eli3_oars_fn_btn") || _q("#_eli3_activity_header_center") || _q("#_eli3_activity_panel"); }
  // Legal Review intake-form elements (present after the user clicks Legal
  // Review). Each returns the card wrapping the control for a clean spotlight.
  function _lrType() { var e = _q("#_eli3_lr_type"); return e ? (e.closest("._eli3_lr_card") || e) : null; }
  function _lrRevised() { var e = _q('input[name="_eli3_lr_revised_by"]'); return e ? (e.closest("._eli3_lr_card") || e) : null; }
  function _lrPaper() { var e = _q('input[name="_eli3_lr_paper"]'); return e ? (e.closest("._eli3_lr_card") || e) : null; }
  function _lrLaunch() { return _q("#_eli3_lr_submit"); }
  // Review Redlines workbench elements (present after Launch Analysis).
  function _rrIndex() { return _q("#tpFocusSidebar"); }
  function _rrMapBtn() { return _q("#tpFocusSectionPillBtn"); }
  // Index button by its visible change number (the sidebar label is the
  // sequential change number). 11 = Publications clause, 12 = the clause with a
  // counterparty comment in the demo doc.
  function _rrIndexBtn(label) {
    var sb = _q("#tpFocusSidebar");
    if (!sb) return null;
    var btns = sb.querySelectorAll("button");
    for (var i = 0; i < btns.length; i++) {
      var n = btns[i].querySelector(".tp-idx-num");
      if (n && (n.textContent || "").trim() === String(label)) return btns[i];
    }
    return null;
  }
  function _rrIndex11() { return _rrIndexBtn(11); }
  function _rrIndex12() { return _rrIndexBtn(12); }
  function _rrIndex17() { return _rrIndexBtn(17); } // locked clause in the demo
  function _rrIndex19() { return _rrIndexBtn(19); } // clause with fallbacks
  function _rrIndex33() { return _rrIndexBtn(33); } // team-guidance demo clause
  function _rrIndex5() { return _rrIndexBtn(5); }   // clause-mapping demo clause
  function _rrClauseMapBtn() { return _q("[data-rr-map-btn]"); } // 📖 mapping button
  function _rrImpact() { return _q("details[data-rr-impact-pane]"); }
  function _rrGuidance() { return _q("details[data-rr-guidance-pane]"); }
  function _rrCommentsBox() { return _q("#tpFocusCounterpartyCommentsBtn"); }
  function _rrAiResponseBox() { return _q("#tpFocusCounterpartyAiBtn"); }
  var STEPS_REVIEW = [
    { title: "Phase 3 — Review Redline", intro: true, cta: "Show me →",
      introTitle: "Welcome to Phase 3 — Review Redline",
      body: "This is an actual revised draft the EI team received back — time to review it. Say hello to Legal Review, your review powerhouse. Let me walk you through it before you start. Give me a few seconds, and please don't click anything until I'm done.",
      target: function () { return null; } },
    { title: "Copy Filename",
      body: "First, this Copy Filename button. One click gives you the correct, standardized file name for the revised draft — no guessing, no typos.",
      target: _copyFnBtn },
    { title: "Three tools in one",
      body: "Legal Review is really three tools working together: Compare Doc, Legal Risks, and Review Redlines. Here's what each one does.",
      target: _lrTile },
    { title: "Compare Doc",
      body: "Compare Doc lines up a third party's template against EI's own template and tells you exactly what's missing.",
      target: _lrTile },
    { title: "Legal Risks",
      body: "Legal Risks runs a general review of the document, flags the legal risks, and suggests fixes.",
      target: _lrTile },
    { title: "Review Redlines",
      body: "Review Redlines is the ultimate tool for reviewing a revised draft. It gives you all the information you need to make an informed decision on whether to accept, reject, or revise a redline. It does that by walking every redline in the document and backing you up with playbook guidance, clause guidance, AI guidance, and more. It also has team guidance — crowdsourced legal review. Your knowledge helps everyone: what you add becomes team guidance the whole team can lean on.",
      target: _lrTile },
    { title: "It picks the right tool",
      body: "Don't worry about which of the three to choose. When you click Legal Review, it runs an AI review of the document and asks you a few questions, then picks the right tool for you automatically.",
      target: _lrTile },
    { title: "ELI knows who changed what",
      body: "Legal Review pulls out which author made each change, so it can guide you based on who made what — a change from a Colgate colleague is viewed very differently than one from a third party. You'll identify each reviewer and whether they work for Colgate or the counterparty.",
      target: _lrTile },
    { title: "Colgate paper, auto-detected",
      body: "ELI also auto-detects whether this is Colgate paper or the third party's. It's usually right — but if it got it wrong, just click it to set it straight.",
      target: _lrTile },
    { title: "Now let's get started", noTuck: true,
      body: "That's the rundown. Now let's actually do it — go ahead and click Legal Review. I'll stay right here, full size, and walk you through the screen that opens. Click Legal Review, then hit Next.",
      target: _lrTile },
    { title: "Confirm the agreement type", noTuck: true, stayInTool: true,
      body: "Welcome to the Legal Review screen. First, confirm the agreement type up top — ELI fills in its best guess, so just make sure it's right. Then hit Next.",
      target: _lrType },
    { title: "Who last revised?", noTuck: true, stayInTool: true,
      body: "Next, who last revised the document? This really matters — ELI guides differently depending on who made each change. The answer here is usually obvious, but in case you need help, the counterparty is the party who last revised. Set it and hit Next.",
      target: _lrRevised },
    { title: "Original source", noTuck: true, stayInTool: true,
      body: "Now the original source — ELI auto-detected this as Colgate Paper (our template, marked up by the other side). Confirm the source is correct and hit Next.",
      target: _lrPaper },
    { title: "Launch Analysis", noTuck: true, stayInTool: true,
      body: "Last check: make sure all three are right — agreement type, who revised, and original source. When they are, click Launch Analysis to begin. After you click it, you'll be asked to identify who made the changes to the document — here's a hint: Daniel Mixell does NOT work for Colgate. ELI then picks the right review and opens it up. Heads up — you may see a \"hidden redlines\" dialog (maybe two), just because the demo treats the earlier draft as this document's first version. In normal use you'd have started fresh, so this won't come up. If you see it, just click Continue. Once you're in Review Redlines, hit Next and I'll keep going.",
