      var r = tgt.getBoundingClientRect();
      _showSpot(r);
      _placeCard(r);
    }
    // Pin to a fixed screen spot (e.g. top-left to point at Script Lab's
    // reload arrow in the host chrome, or left-middle for narration boxes).
    // Respects a user drag, so it only snaps on first render.
    if (step.pin && !_dragPos && _els.card) {
      var pc = _els.card;
      if (step.pin === "topleft") {
        pc.style.left = "16px"; pc.style.top = "16px";
      } else if (step.pin === "leftmid") {
        pc.style.left = "16px";
        pc.style.top = Math.max(16, Math.round((_vh() - pc.offsetHeight) / 2)) + "px";
      } else if (step.pin === "bottomright") {
        pc.style.left = Math.max(16, Math.round(_vw() - pc.offsetWidth - 16)) + "px";
        pc.style.top = Math.max(16, Math.round(_vh() - pc.offsetHeight - 16)) + "px";
      } else if (step.pin === "topright") {
        pc.style.left = Math.max(16, Math.round(_vw() - pc.offsetWidth - 16)) + "px";
        pc.style.top = "16px";
      }
    }
    // Clicking the highlighted element drops the dim so the user can freely
    // explore what it opens (Settings panel, etc.); the card stays for Next.
    _wireTargetClick(tgt, step);
    _els.card.classList.remove("_in"); void _els.card.offsetWidth; _els.card.classList.add("_in");
  }

  // Attach the "click the highlighted element → tuck ELI" handler to the live
  // target. Re-callable: detaches any prior handler first, so it survives a
  // host re-render (e.g. the Build Draft hub re-rendering between steps, which
  // otherwise left the handler on a stale node — Step 4 wouldn't minimize).
  function _wireTargetClick(tgt, step) {
    _detachTarget();
    // step.noTuck: keep ELI maximized when the highlighted element is clicked
    // (Phase 3 — clicking Legal Review / form controls shouldn't minimize the
    // narrator, since the next stops point at the screen that just opened).
    if (!tgt || step.dim === false || step.noTuck) return;
    _targetEl = tgt;
    _targetClick = function () {
      _spotPaused = true; _hideSpot();
      if (_els.card) {
        _els.card.classList.add("_min");
        // Refresh the header so the min/max button flips to "Maximize".
        _renderCard(STEPS[_idx]);
        _tuckBottomRight();
      }
    };
    try { tgt.addEventListener("click", _targetClick); } catch (_e) {}
  }

  // Park the (already-collapsed) card in the bottom-right corner, out of the
  // way of whatever the user is doing. Measured after the _min class is on so
  // the collapsed height is used. Shared by the target-click tuck and the
  // header Minimize button so both land in the same spot.
  function _tuckBottomRight() {
    var c = _els.card;
    if (!c) return;
    var w = c.offsetWidth, h = c.offsetHeight;
    var nl = Math.max(8, _vw() - w - 16);
    var nt = Math.max(8, _vh() - h - 16);
    c.style.left = nl + "px"; c.style.top = nt + "px";
    _dragPos = { x: nl, y: nt };
  }

  // Tuck ELI into the corner for "explore on your own" stops (step.minimizeOnNext):
  // the trainee reads the message, clicks "Minimize & explore", and ELI shrinks to
  // the corner with a "Click when done" button. Same end state as a target tuck.
  function _autoMinimize() {
    if (!_els.card) return;
    _spotPaused = true;
    _hideSpot();
    _els.card.classList.add("_min");
    _renderCard(STEPS[_idx]); // re-render so the Next button flips to pausedNextLabel
    _tuckBottomRight();
  }

  // The card is collapsed when the user minimized it (— button) OR when they
  // clicked the highlighted element (which auto-tucks it). The min/max button
  // reflects EITHER cause so one click always restores.
  function _isMin() { return _userMin || _spotPaused; }

  // Toggle between minimized and maximized. One click each way regardless of
  // how it collapsed — maximizing clears BOTH collapse causes and fully
  // restores the step (card + spotlight) beside its target.
  function _toggleMin() {
    if (_isMin()) {
      _userMin = false;
      _spotPaused = false;
      _dragPos = null; // return to the natural position beside the target
      _renderStep(STEPS[_idx]);
    } else {
      _userMin = true;
      _hideSpot();
      if (_els.card) _els.card.classList.add("_min");
      _renderCard(STEPS[_idx]); // refresh button glyph/title + body visibility
      _tuckBottomRight();        // park it out of the way, same as a target tuck
    }
  }

  // Navigate to step i, running the prior step's after() then the new
  // step's before() so menu/dialog state is correct in both directions.
  function _go(i) {
    if (!_active) return;
    i = Math.max(0, Math.min(STEPS.length - 1, i));
    var prev = STEPS[_idx];
    var leaving = (i !== _idx) ? prev : null;
    var wasPaused = _spotPaused; // user clicked into something (e.g. Settings)
    _dragPos = null;
    _spotPaused = false;
    _userMin = false;
    _detachTarget();
    var p = Promise.resolve();
    // Safety net: if we're not currently on the dashboard — you opened
    // Settings, launched a tool, etc. — Next returns home FIRST so the next
    // stop's target exists. _eli3_dashboard_main is only present on the
    // dashboard; tool/settings views replace it. goHome is the kernel's
    // full home reset (there is no eli.dashboard.render).
    // EXCEPTION: the Phase 2 Build Draft scripts live INSIDE the Build Draft
    // hub — Next must NOT navigate home there. The Phase 3 in-tool stops (Legal
    // Review form + Review Redlines) carry step.stayInTool for the same reason.
    // Everything else keeps the safety net so dashboard spotlights resolve.
    var destStep = STEPS[i];
    var inBuild = (_resumeKind === "build" || _resumeKind === "build_resume");
    var stayInTool = inBuild || (destStep && destStep.stayInTool);
    // goHome ONLY when the destination genuinely lives on the dashboard
    // (needsHome — e.g. the Final Review tile), or the Phase-1 safety net: the
    // user clicked into something (wasPaused) and the next stop isn't in-tool.
    // Never goHome between two in-tool stops — that's what was yanking Phase 3 /
    // Review Redlines back to the dashboard on Next.
    var needsHome = !!(destStep && destStep.needsHome);
    if ((needsHome || (!stayInTool && wasPaused)) && eli.dashboard && typeof eli.dashboard.goHome === "function") {
      p = p.then(function () { try { eli.dashboard.goHome(); } catch (_e) {} return _wait(300); });
    }
    if (leaving && leaving.after) p = p.then(function () { return leaving.after(); });
    _idx = i;
    var step = STEPS[_idx];
    p.then(function () { return step.before ? step.before() : null; })
     .then(function () { if (_active) _renderStep(step); })
     .catch(function () { if (_active) _renderStep(step); });
  }

  // Re-resolve the current target and re-wrap it. The tour is interactive —
  // users click highlighted elements, which open menus / shift layout, so the
  // spotlight tracks the live position. If the target navigated away (e.g. a
  // tile launched a tool), hide the spotlight so nothing is obscured. The
  // card is NOT repositioned here (respects drag + avoids jitter).
  // Hide the entire tour while a kernel dialog (.eli-overlay) OR the unpinned
  // apps menu is open, so those show ABOVE the tour and the spotlight ring
  // isn't drawn over the "+" you just clicked. Checked doc-wide because the
  // unpinned menu attaches to the "+" wrap, not <body>.
  function _syncOverlayVisibility() {
    if (!_active || !_els.root) return;
    var blocking = document.querySelector(".eli-overlay")
      || document.getElementById("_eli3_unpinned_menu")
      || document.getElementById("_agls_backdrop"); // Agreement at a Glance slide-up
    _els.root.style.visibility = blocking ? "hidden" : "";
  }

  function _relayoutCurrent() {
    if (!_active) return;
    _syncOverlayVisibility();
    if (_spotPaused || _userMin) return;
    var step = STEPS[_idx];
    if (!step || step.dim === false || step.intro) return; // intro keeps its full backdrop
    var tgt = null;
    try { tgt = step.target ? step.target() : null; } catch (_e) {}
    if (!tgt) { _hideSpot(); return; }
    var r = tgt.getBoundingClientRect();
    if (r.width === 0 && r.height === 0) { _hideSpot(); return; }
    _showSpot(r);
    // If the host re-rendered the target (new DOM node), re-attach the
    // click-to-tuck handler so it always follows the live highlighted element.
    if (tgt !== _targetEl) _wireTargetClick(tgt, step);
  }

  function _bind() {
    _onResize = function () { if (_active) _renderStep(STEPS[_idx]); };
    window.addEventListener("resize", _onResize);
    _relayoutTimer = setInterval(_relayoutCurrent, 400);
    // Step fully aside whenever a kernel dialog (.eli-overlay) is open — the
    // ELI AI Help/Contact dialog, etc. — so it's never obscured by the tour,
    // independent of z-index. Restore when the dialog closes.
    if (typeof MutationObserver === "function") {
      _dlgObserver = new MutationObserver(function () { _syncOverlayVisibility(); });
      try { _dlgObserver.observe(document.body, { childList: true, subtree: true }); } catch (_e) {}
    }
    _onKey = function (e) {
      if (!_active) return;
      if (e.key === "Escape") { _end(); }
      else if (e.key === "ArrowRight") { if (_idx < STEPS.length - 1) _go(_idx + 1); }
      else if (e.key === "ArrowLeft") { if (_idx > 0) _go(_idx - 1); }
    };
    document.addEventListener("keydown", _onKey, true);
    // Home stays clickable during the tour (the dim is pointer-events:none, so
    // the kernel's own go-home handler runs) but it does NOT end the tour —
    // the overlay persists on <body> and the spotlight re-resolves after the
    // dashboard re-renders. Use the — minimize button or ✕ / Esc to exit.
  }
  function _unbind() {
    if (_onResize) window.removeEventListener("resize", _onResize);
    if (_onKey) document.removeEventListener("keydown", _onKey, true);
    if (_relayoutTimer) { clearInterval(_relayoutTimer); _relayoutTimer = null; }
    if (_dlgObserver) { try { _dlgObserver.disconnect(); } catch (_e) {} _dlgObserver = null; }
    _onResize = _onKey = null;
  }

  function _end() {
    if (!_active) return;
    _active = false;
    _spotPaused = false;
    _userMin = false;
    // Finish/✕ before reloading cancels the pending Phase 2 resume.
    _resumeKind = null;
    _clearResume();
    _detachTarget();
    _closeUnpinned();
    _unbind();
    if (_els.card) { _els.card.classList.add("_out"); }
    setTimeout(_teardownDom, 180);
    try { eli.log.event("tool", "dashboard_tour_ended", { atStep: _idx }); } catch (_e) {}
  }

  function _startTour(steps, opts) {
    if (_active) return;
    opts = opts || {};
    STEPS = steps || STEPS_DASH;
    // Which script persists across a reload (build/build_resume = Phase 2;
    // review = Phase 3). Others don't persist.
    _resumeKind = (STEPS === STEPS_BUILD) ? "build"
      : (STEPS === STEPS_BUILD_RESUME) ? "build_resume"
      : (STEPS === STEPS_REVIEW) ? "review"
      : (STEPS === STEPS_ASKELI) ? "askeli" : null;
    _active = true;
    try { if (eli.stats && eli.stats.record) eli.stats.record("appOpenedTour"); } catch (_e) {}
    var startAt = (opts.startAt && opts.startAt > 0) ? Math.min(STEPS.length - 1, opts.startAt) : 0;
    // opts.noHome: skip the goHome reset — used by the Phase 2 resume so the
    // narrator overlays the live Build Draft run instead of navigating away.
    var pre = (!opts.noHome && eli.dashboard && typeof eli.dashboard.goHome === "function") ? Promise.resolve(eli.dashboard.goHome()) : Promise.resolve();
    Promise.resolve(pre).then(function () { return _wait(220); }).then(function () {
      if (!_active) return;
      _ensureDom(); _bind();
      _idx = startAt;
      var s = STEPS[_idx];
      return (s.before ? Promise.resolve(s.before()) : Promise.resolve()).then(function () {
        if (_active) _renderStep(s);
      });
    }).catch(function () { if (_active && _els.card) _renderStep(STEPS[_idx] || STEPS[0]); });
  }

  // No tile — the tour is launched only via this channel (Demo Director
  // Phase 1 dispatches eli.dispatch("tour", "start")).
  eli.register({
    tour: {
      start: function () { _startTour(STEPS_DASH); },
      buildDraft: function () { _startTour(STEPS_BUILD); },
      reviewReload: function () { _startTour(STEPS_REVIEW_RELOAD); },
      reviewDraft: function () { _startTour(STEPS_REVIEW); },
      askEliReload: function () { _startTour(STEPS_ASKELI_RELOAD); },
      askEli: function () { _startTour(STEPS_ASKELI); },
    },
  });

  // Auto-resume after a Script Lab reload: if the user reloaded while on the
  // Phase 2 "reload to begin" stop, bring the narrator back once to ride
  // along with the live Build Draft run. Cleared immediately so it fires only
  // once; delayed so Build Draft has a moment to launch first. noHome keeps it
  // from navigating away from the Build Draft flow.
  (function _maybeResume() {
    try {
      if (!eli.storage || typeof eli.storage.get !== "function") return;
      eli.storage.get(_CFG, RESUME_KEY).then(function (row) {
        if (!row) return;
        var kind = row.resume, step = row.step || 0;
        var script = kind === "build" ? STEPS_BUILD
          : kind === "build_resume" ? STEPS_BUILD_RESUME
          : kind === "review" ? STEPS_REVIEW
          : kind === "askeli" ? STEPS_ASKELI : null;
        if (!script) return;
        _clearResume();
        // Build Draft scripts overlay the live Build Draft run (noHome); the
        // Phase 3 review + Phase 4 Ask ELI walkthroughs go home to spotlight the
        // dashboard (Legal Review tile / Ask ELI bar).
        var opts = (kind === "review" || kind === "askeli") ? { startAt: step } : { noHome: true, startAt: step };
        setTimeout(function () { if (!_active) _startTour(script, opts); }, 2500);
      }).catch(function () {});
    } catch (_e) {}
  })();
}

jsonTools.css:
/* dashboard_tour — premium guided tour overlay. Navy/gold to match the
   ELI dashboard chrome. Sized for laptops (compact card). */

/* z below kernel dialogs (9999+) so the Help/Contact, Settings, and Customize
   dialogs the tour invites you to open render ABOVE the spotlight. Still well
   above dashboard chrome. */
#_eli3_tour_root { position: fixed; inset: 0; z-index: 9500; pointer-events: none; }

/* Single spotlight: a transparent box over the target. Its enormous
   box-shadow dims the whole screen (no width math → immune to laptop zoom);
   the gold border is the ring. pointer-events:none so the Home button and the
   rest of the chrome stay clickable. */
._eli3_tour_spot {
  position: fixed; pointer-events: none; border-radius: 12px;
  border: 2px solid #c9a227;
  box-shadow: 0 0 0 9999px rgba(13, 27, 42, 0.62),
              0 0 0 3px rgba(201, 162, 39, 0.22), 0 0 22px 4px rgba(201, 162, 39, 0.45);
  z-index: 100002;
  transition: left 0.28s cubic-bezier(0.4, 0, 0.2, 1), top 0.28s cubic-bezier(0.4, 0, 0.2, 1),
              width 0.28s cubic-bezier(0.4, 0, 0.2, 1), height 0.28s cubic-bezier(0.4, 0, 0.2, 1);
  animation: _eli3_tour_pulse 2s ease-in-out infinite;
}
/* Intro splash — full backdrop, no visible ring (0-size box, shadow only). */
._eli3_tour_spot._nohole { border-color: transparent; animation: none; }
@keyframes _eli3_tour_pulse {
  0%, 100% { box-shadow: 0 0 0 9999px rgba(13,27,42,0.62), 0 0 0 3px rgba(201,162,39,0.20), 0 0 18px 3px rgba(201,162,39,0.38); }
  50%      { box-shadow: 0 0 0 9999px rgba(13,27,42,0.62), 0 0 0 4px rgba(201,162,39,0.30), 0 0 26px 6px rgba(201,162,39,0.55); }
}

/* The mascot speech card */
._eli3_tour_card {
  position: fixed; z-index: 100010; pointer-events: auto;
  width: min(300px, 88vw); box-sizing: border-box;
  background: linear-gradient(160deg, #0d1b2a 0%, #1b263b 100%);
  border: 1px solid rgba(201, 162, 39, 0.55); border-radius: 14px;
  box-shadow: 0 18px 50px rgba(13, 27, 42, 0.55), 0 2px 0 rgba(255, 255, 255, 0.04) inset;
  color: #e2e8f0; overflow: hidden;
  font-family: 'Inter', 'Segoe UI', sans-serif;
  transition: left 0.28s cubic-bezier(0.4, 0, 0.2, 1), top 0.28s cubic-bezier(0.4, 0, 0.2, 1);
}
._eli3_tour_card._in { animation: _eli3_tour_cardin 0.26s cubic-bezier(0.34, 1.4, 0.5, 1); }
._eli3_tour_card._out { opacity: 0; transform: scale(0.97); transition: opacity 0.16s ease, transform 0.16s ease; }
@keyframes _eli3_tour_cardin {
  0% { opacity: 0; transform: translateY(6px) scale(0.98); }
  100% { opacity: 1; transform: translateY(0) scale(1); }
}

._eli3_tour_accent {
  height: 3px; width: 100%;
  background: linear-gradient(90deg, #b8901f 0%, #f2d866 50%, #b8901f 100%);
}

/* ── Intro splash — giant ELI welcome ───────────────────────────────── */
._eli3_tour_card._intro {
  width: min(440px, 92vw); text-align: center; padding-bottom: 22px;
}
._eli3_tour_x_intro {
  position: absolute; top: 8px; right: 10px;
  border: none; background: transparent; color: #94a3b8;
  font-size: 15px; line-height: 1; cursor: pointer; padding: 2px 5px; border-radius: 5px;
}
._eli3_tour_x_intro:hover { color: #e2e8f0; background: rgba(255, 255, 255, 0.08); }
._eli3_tour_introav {
  width: 104px; height: 104px; margin: 22px auto 6px; border-radius: 50%;
  background: radial-gradient(circle at 50% 35%, #16263c, #0b1626);
  border: 2px solid #c9a227; box-shadow: 0 0 26px rgba(201, 162, 39, 0.45);
  display: flex; align-items: center; justify-content: center; overflow: hidden;
}
._eli3_tour_introav svg, ._eli3_tour_introav img { width: 86%; height: 86%; display: block; }
._eli3_tour_introtitle {
  font: 800 22px/1.2 Georgia, 'Book Antiqua', serif; color: #f2d866;
  margin: 6px 22px 0;
}
._eli3_tour_introtxt {
  font: 400 14px/1.6 Inter, sans-serif; color: #cbd5e1; margin: 12px 26px 20px;
  max-height: 44vh; overflow: auto;
}
._eli3_tour_introbtns { display: flex; justify-content: center; align-items: center; gap: 10px; }
._eli3_tour_back_intro { padding: 11px 18px; font-size: 12px; }
._eli3_tour_next_intro {
  border: 1px solid #b8901f; color: #3a2c05; font: 800 13px/1 Inter, sans-serif;
  padding: 11px 26px; border-radius: 9px; cursor: pointer;
  background: linear-gradient(135deg, #f2d866 0%, #c9a227 60%, #b8901f 100%);
  box-shadow: 0 3px 12px rgba(201, 162, 39, 0.45), inset 0 1px 0 rgba(255, 255, 255, 0.5);
  transition: filter 0.12s ease, transform 0.12s ease;
}
._eli3_tour_next_intro:hover { filter: brightness(1.06); transform: translateY(-1px); }
._eli3_tour_next_intro:active { transform: translateY(0); }

._eli3_tour_hd {
  display: flex; align-items: center; gap: 10px; padding: 11px 12px 9px; cursor: move;
  border-bottom: 1px solid rgba(255, 255, 255, 0.07); user-select: none;
}
._eli3_tour_av {
  flex: 0 0 auto; width: 40px; height: 40px; border-radius: 50%;
  background: radial-gradient(circle at 50% 35%, #16263c, #0b1626);
  border: 1.5px solid #c9a227; box-shadow: 0 0 14px rgba(201, 162, 39, 0.35);
  display: flex; align-items: center; justify-content: center; overflow: hidden;
}
._eli3_tour_av svg, ._eli3_tour_av img { width: 88%; height: 88%; display: block; }
._eli3_tour_idwrap { display: flex; flex-direction: column; gap: 1px; flex: 1 1 auto; min-width: 0; }
._eli3_tour_name { font: 800 13px/1 Georgia, 'Book Antiqua', serif; letter-spacing: 0.04em; color: #f2d866; }
._eli3_tour_sub { font: 600 8.5px/1 Inter, sans-serif; letter-spacing: 0.16em; text-transform: uppercase; color: #7c8aa0; }
._eli3_tour_minbtn {
  flex: 0 0 auto; border: 1px solid rgba(201, 162, 39, 0.45);
  background: rgba(201, 162, 39, 0.12); color: #f2d866;
  font: 800 10px/1 Inter, sans-serif; letter-spacing: 0.03em; cursor: pointer;
  padding: 4px 7px; border-radius: 6px;
}
._eli3_tour_minbtn:hover { color: #fff; background: rgba(201, 162, 39, 0.24); }
._eli3_tour_x {
  flex: 0 0 auto; border: none; background: transparent; color: #94a3b8;
  font-size: 14px; line-height: 1; cursor: pointer; padding: 2px 4px; border-radius: 5px;
}
._eli3_tour_x:hover { color: #e2e8f0; background: rgba(255, 255, 255, 0.08); }

/* Collapsed state — shown while the user is exploring a clicked element
   (e.g. Settings). Only the header + Back/Next remain so the panel is clear. */
._eli3_tour_card._min ._eli3_tour_body { display: none; }
._eli3_tour_card._min ._eli3_tour_hd { border-bottom: none; }

._eli3_tour_body { padding: 11px 14px 4px; }
._eli3_tour_title { font: 700 14px/1.25 Georgia, 'Book Antiqua', serif; color: #fff; margin-bottom: 5px; }
._eli3_tour_txt { font: 400 12.5px/1.55 Inter, sans-serif; color: #cbd5e1; }

._eli3_tour_ft {
  display: flex; align-items: center; justify-content: space-between; gap: 10px;
  padding: 10px 14px 13px;
}
/* Many stops now — let the dots stay compact and wrap rather than push the
   Back/Next buttons off the card edge. */
._eli3_tour_dots { display: flex; align-items: center; flex-wrap: wrap; gap: 3px; flex: 1 1 auto; min-width: 0; }
._eli3_tour_dot {
  width: 5px; height: 5px; border-radius: 50%; background: rgba(255, 255, 255, 0.20);
  transition: background 0.2s ease, transform 0.2s ease;
}
._eli3_tour_dot._on { background: #c9a227; transform: scale(1.25); box-shadow: 0 0 8px rgba(201, 162, 39, 0.6); }
._eli3_tour_btns { display: flex; align-items: center; gap: 7px; flex: 0 0 auto; }

._eli3_tour_back {
  border: 1px solid rgba(255, 255, 255, 0.18); background: rgba(255, 255, 255, 0.06);
  color: #cbd5e1; font: 700 11px/1 Inter, sans-serif; padding: 7px 11px; border-radius: 7px;
  cursor: pointer; transition: background 0.12s ease;
}
._eli3_tour_back:hover { background: rgba(255, 255, 255, 0.13); }
._eli3_tour_next {
  border: 1px solid #b8901f; color: #3a2c05; font: 800 11px/1 Inter, sans-serif;
  padding: 7px 14px; border-radius: 7px; cursor: pointer;
  background: linear-gradient(135deg, #f2d866 0%, #c9a227 60%, #b8901f 100%);
  box-shadow: 0 2px 8px rgba(201, 162, 39, 0.4), inset 0 1px 0 rgba(255, 255, 255, 0.5);
  transition: filter 0.12s ease, transform 0.12s ease;
}
._eli3_tour_next:hover { filter: brightness(1.06); transform: translateY(-1px); }
._eli3_tour_next:active { transform: translateY(0); }
